-- 总部与下属企业照片、标题和简介归入同一企业记录。仅首次补充缺失配置，按企业 ID 关联，保留原联系方式、顺序、显示开关及邮件设置。
SET NAMES utf8mb4;
START TRANSACTION;
UPDATE site_settings SET configuration=JSON_SET(configuration,'$.contact.facility',CAST(CONVERT( USING utf8mb4) AS JSON))
WHERE id='contact' AND JSON_CONTAINS_PATH(configuration,'one','$.contact.facility')=0 AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-16-contact-facilities-v1');
UPDATE site_settings SET configuration=JSON_SET(configuration,REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','zhenhan',NULL,'$.subsidiaries[*].id')),'.id','.facility'),CAST(CONVERT( USING utf8mb4) AS JSON))
WHERE id='contact' AND JSON_SEARCH(configuration,'one','zhenhan',NULL,'$.subsidiaries[*].id') IS NOT NULL AND JSON_CONTAINS_PATH(configuration,'one',REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','zhenhan',NULL,'$.subsidiaries[*].id')),'.id','.facility'))=0 AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-16-contact-facilities-v1');
UPDATE site_settings SET configuration=JSON_SET(configuration,REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','greenland',NULL,'$.subsidiaries[*].id')),'.id','.facility'),CAST(CONVERT( USING utf8mb4) AS JSON))
WHERE id='contact' AND JSON_SEARCH(configuration,'one','greenland',NULL,'$.subsidiaries[*].id') IS NOT NULL AND JSON_CONTAINS_PATH(configuration,'one',REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','greenland',NULL,'$.subsidiaries[*].id')),'.id','.facility'))=0 AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-16-contact-facilities-v1');
INSERT INTO app_migrations (id) SELECT '2026-10-16-contact-facilities-v1' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-16-contact-facilities-v1');
COMMIT;
